//! `PointPrimitiveCollection` against a capture of the pinned CesiumJS engine
//! on a real WebGL2 context, `tests/data/scene-point-primitive-collection.json`
//! (generated by `tools/cesium/generate-scene-point-primitive-collection.mjs`).
//! Each scenario is replayed through a recording WebGL host and, after every
//! update, compared on the exact vertex bytes Cesium uploads, the draw
//! commands, the shader defines and the collection's bookkeeping.

use base64::Engine;
use cesium_rs::core::*;
use cesium_rs::renderer::{Context, Gl, GlValue, UniformFrame, UniformFrustum};
use cesium_rs::scene::point_primitive::*;
use cesium_rs::scene::point_primitive_collection::*;
use cesium_rs::scene::{
    BlendOption, Camera, CameraFrustum, CameraOptions, FrameResource, FrameState, SceneMode, ScenePrimitive,
    SceneTransformState, SplitDirection,
};
use serde_json::{json, Value};
use std::{
    cell::{Cell, RefCell},
    rc::Rc,
};

const ACTIVE_ATTRIBUTES: f64 = 35721.0;
const ACTIVE_UNIFORMS: f64 = 35718.0;
const ALIASED_POINT_SIZE_RANGE: f64 = 33901.0;
const ALIASED_LINE_WIDTH_RANGE: f64 = 33902.0;
const MAX_VIEWPORT_DIMS: f64 = 3386.0;

/// A WebGL host that accepts every call, reports the point attributes as
/// active, an 8×8 drawing buffer (the capture's canvas) and the capture's
/// maximum aliased point size.
#[derive(Clone)]
struct Host {
    next: Rc<Cell<u32>>,
    max_point_size: f64,
    /// Vertex uploads, in the capture's `[call, usage or offset, length, hash]` form.
    uploads: Rc<RefCell<Vec<Value>>>,
}

const ATTRIBUTES: [&str; 6] = [
    "positionHighAndSize",
    "positionLowAndOutline",
    "compressedAttribute0",
    "compressedAttribute1",
    "scaleByDistance",
    "distanceDisplayConditionAndDisableDepthAndSplitDirection",
];

impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([8, 8])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        let number = |i: usize| match args.get(i) {
            Some(GlValue::Number(n)) => Some(*n),
            _ => None,
        };
        const ARRAY_BUFFER: f64 = 34962.0;
        match (name, args) {
            ("bufferData", [GlValue::Number(ARRAY_BUFFER), GlValue::Bytes(b), GlValue::Number(usage)]) => {
                self.uploads.borrow_mut().push(json!(["bufferData", usage, b.len(), fnv(b)]))
            }
            ("bufferSubData", [GlValue::Number(ARRAY_BUFFER), GlValue::Number(offset), GlValue::Bytes(b)]) => {
                self.uploads.borrow_mut().push(json!(["bufferSubData", offset, b.len(), fnv(b)]))
            }
            _ => {}
        }
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" => match number(0) {
                    Some(ALIASED_POINT_SIZE_RANGE) => GlValue::Numbers(vec![1., self.max_point_size]),
                    Some(ALIASED_LINE_WIDTH_RANGE) | Some(MAX_VIEWPORT_DIMS) => GlValue::Numbers(vec![1., 4096.]),
                    _ => GlValue::Number(4096.),
                },
                "getExtension" => GlValue::Object(0),
                "getProgramParameter" if number(1) == Some(ACTIVE_ATTRIBUTES) => GlValue::Number(6.),
                "getProgramParameter" if number(1) == Some(ACTIVE_UNIFORMS) => GlValue::Number(0.),
                "getActiveAttrib" => {
                    let index = number(1).unwrap_or(0.) as usize;
                    GlValue::Record(json!({"name": ATTRIBUTES[index], "type": 35666, "size": 1}))
                }
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                _ => GlValue::Null,
            }
        })
    }
}

fn fnv(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in bytes {
        h = (h ^ *b as u64).wrapping_mul(0x100000001b3);
    }
    format!("{h:x}")
}

fn floats(bytes: &[u8]) -> Vec<f32> {
    bytes.chunks(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect()
}

fn num(v: &Value) -> f64 {
    match v {
        Value::String(s) if s == "Infinity" => f64::INFINITY,
        Value::String(s) if s == "-Infinity" => f64::NEG_INFINITY,
        _ => v.as_f64().unwrap(),
    }
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(num).collect()
}

fn c3(v: &Value) -> Cartesian3 {
    let n = nums(v);
    Cartesian3::new(n[0], n[1], n[2])
}

fn color(v: &Value) -> Color {
    let n = nums(v);
    Color::new(n[0], n[1], n[2], n[3])
}

fn scalar(v: &Value) -> Option<NearFarScalar> {
    (!v.is_null()).then(|| {
        let n = nums(v);
        NearFarScalar::new(n[0], n[1], n[2], n[3])
    })
}

fn condition(v: &Value) -> Option<DistanceDisplayCondition> {
    (!v.is_null()).then(|| {
        let n = nums(v);
        DistanceDisplayCondition::new(n[0], n[1])
    })
}

fn options(o: &Value) -> PointPrimitiveOptions {
    let mut p = PointPrimitiveOptions::default();
    for (k, v) in o.as_object().unwrap() {
        match k.as_str() {
            "position" => p.position = c3(v),
            "color" => p.color = color(v),
            "outlineColor" => p.outline_color = color(v),
            "outlineWidth" => p.outline_width = num(v),
            "pixelSize" => p.pixel_size = num(v),
            "show" => p.show = v.as_bool().unwrap(),
            "id" => p.id = v.as_str().map(String::from),
            "scaleByDistance" => p.scale_by_distance = scalar(v),
            "translucencyByDistance" => p.translucency_by_distance = scalar(v),
            "distanceDisplayCondition" => p.distance_display_condition = condition(v),
            "disableDepthTestDistance" => p.disable_depth_test_distance = num(v),
            other => panic!("unknown option {other}"),
        }
    }
    p
}

fn set(point: &PointPrimitive, property: &str, v: &Value) {
    match property {
        "position" => point.set_position(c3(v)),
        "color" => point.set_color(color(v)),
        "outlineColor" => point.set_outline_color(color(v)),
        "outlineWidth" => point.set_outline_width(num(v)),
        "pixelSize" => point.set_pixel_size(num(v)),
        "show" => point.set_show(v.as_bool().unwrap()),
        "splitDirection" => point.set_split_direction(SplitDirection::from_value(v.as_i64().unwrap() as i32).unwrap()),
        "scaleByDistance" => point.set_scale_by_distance(scalar(v)).unwrap(),
        "translucencyByDistance" => point.set_translucency_by_distance(scalar(v)).unwrap(),
        "distanceDisplayCondition" => point.set_distance_display_condition(condition(v)).unwrap(),
        "disableDepthTestDistance" => point.set_disable_depth_test_distance(num(v)).unwrap(),
        other => panic!("unknown property {other}"),
    }
}

/// The capture's camera, as the frame's uniform camera.
fn frame(context: &Context<Host>, camera: &Value) -> FrameState {
    let frustum = PerspectiveFrustum {
        fov: std::f64::consts::PI / 3.,
        aspect_ratio: 4. / 3.,
        near: 1.,
        far: 1e9,
        ..PerspectiveFrustum::new(std::f64::consts::PI / 3., 4. / 3.)
    };
    let (position, direction, up, right) =
        (c3(&camera["position"]), c3(&camera["direction"]), c3(&camera["up"]), c3(&camera["right"]));
    let view = Matrix4::compute_view(position, direction, up, right);
    let uniform = cesium_rs::renderer::UniformCamera {
        view,
        inverse_view: view.inverse_transformation(),
        position,
        direction,
        right,
        up,
        cartographic: None,
        frustum: UniformFrustum::Perspective(frustum),
    };
    let culling = frustum.compute_culling_volume(position, direction, up);
    let mut frame =
        FrameState::new(UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)), culling, [8, 8]);
    frame.context = Some(FrameResource::new(context.clone()));
    frame.pixel_ratio = 1.;
    frame
}

fn assert_close(actual: f64, expected: &Value, context: &str) {
    let expected = num(expected);
    let tolerance = 1e-9 * expected.abs().max(1.);
    assert!(actual == expected || (actual - expected).abs() <= tolerance, "{context}: {actual} != {expected}");
}

fn check_step(
    collection: &PointPrimitiveCollection<Host>,
    points: &[PointPrimitive],
    step: &Value,
    previous: &mut (Option<usize>, Option<usize>),
    context: &str,
) {
    // Vertex buffers, by usage, byte for byte.
    let buffers: Vec<Value> = collection.vertex_array_facade().map_or_else(Vec::new, |vaf| {
        vaf.buffer_layouts()
            .into_iter()
            .map(|(usage, stride, bytes)| {
                json!({"usage": usage as u32, "vertexSizeInBytes": stride, "hash": fnv(bytes), "length": bytes.len(), "bytes": bytes})
            })
            .collect()
    });
    let expected = step["buffers"].as_array().unwrap();
    assert_eq!(buffers.len(), expected.len(), "{context}: buffer count");
    for (i, (b, e)) in buffers.iter().zip(expected).enumerate() {
        for key in ["usage", "vertexSizeInBytes", "length"] {
            assert_eq!(b[key], e[key], "{context}: buffer {i} {key}");
        }
        if b["hash"] != e["hash"] {
            let actual: Vec<u8> = serde_json::from_value(b["bytes"].clone()).unwrap();
            let detail = match e["bytes"].as_str() {
                Some(b64) => {
                    let wanted = base64::engine::general_purpose::STANDARD.decode(b64).unwrap();
                    format!("\n actual   {:?}\n expected {:?}", floats(&actual), floats(&wanted))
                }
                None => String::new(),
            };
            panic!("{context}: buffer {i} bytes differ{detail}");
        }
    }
    let va_count = collection.vertex_array_facade().and_then(|v| v.vertex_arrays()).map_or(0, |v| v.len());
    assert_eq!(json!(va_count), step["vaCount"], "{context}: vaCount");

    // Commands.
    let commands = collection.commands();
    let expected = step["commands"].as_array().unwrap();
    assert_eq!(commands.len(), expected.len(), "{context}: command count");
    for (i, (c, e)) in commands.iter().zip(expected).enumerate() {
        let ctx = format!("{context}: command {i}");
        assert_eq!(json!(c.pass as u32), e["pass"], "{ctx} pass");
        assert_eq!(json!(c.primitive_type as u32), e["primitiveType"], "{ctx} primitiveType");
        assert_eq!(json!(c.vertex_array), e["vaIndex"], "{ctx} vaIndex");
        let (sp, _) = collection.shader_programs();
        assert_eq!(json!(c.opaque_program && sp.is_some()), e["opaqueProgram"], "{ctx} opaqueProgram");
        let rs = &c.render_state;
        assert_eq!(json!(rs.depth_test.enabled), e["renderState"]["depthTest"], "{ctx} depthTest");
        assert_eq!(json!(rs.depth_test.func), e["renderState"]["depthFunc"], "{ctx} depthFunc");
        assert_eq!(json!(rs.depth_mask), e["renderState"]["depthMask"], "{ctx} depthMask");
        assert_eq!(json!(rs.blending.enabled), e["renderState"]["blending"], "{ctx} blending");
        let bv = c.bounding_volume;
        for (k, v) in [bv.center.x, bv.center.y, bv.center.z, bv.radius].iter().enumerate() {
            assert_close(*v, &e["boundingVolume"][k], &format!("{ctx} boundingVolume[{k}]"));
        }
        assert_eq!(c.model_matrix.0.to_vec(), nums(&e["modelMatrix"]), "{ctx} modelMatrix");
        assert_eq!(json!(c.pick_id), e["pickId"], "{ctx} pickId");
        assert_eq!(json!(c.debug_show_bounding_volume), e["debugShowBoundingVolume"], "{ctx} debugShowBoundingVolume");
        assert_eq!(collection.max_total_point_size(), num(&e["maxTotalPointSize"]), "{ctx} maxTotalPointSize");
    }

    // Programs: defines and whether each was replaced.
    let program = |p: Option<&PointPrimitiveProgram>| {
        p.map_or(Value::Null, |p| json!({"vs": p.vertex_defines, "fs": p.fragment_defines}))
    };
    let (sp, sp_translucent) = collection.programs();
    assert_eq!(program(sp), step["sp"], "{context}: sp");
    assert_eq!(program(sp_translucent), step["spTranslucent"], "{context}: spTranslucent");
    let (sp, sp_translucent) = collection.shader_programs();
    let address = |p: Option<Rc<_>>| p.map(|p: Rc<_>| Rc::as_ptr(&p) as *const () as usize);
    let current = (address(sp), address(sp_translucent));
    assert_eq!(json!(current.0 != previous.0), step["spChanged"], "{context}: spChanged");
    assert_eq!(json!(current.1 != previous.1), step["spTranslucentChanged"], "{context}: spTranslucentChanged");
    *previous = current;

    // Bookkeeping.
    let f = &step["flags"];
    let flags = collection.shader_flags();
    assert_eq!(json!(flags.scale_by_distance), f["scaleByDistance"], "{context}: scaleByDistance");
    assert_eq!(json!(flags.translucency_by_distance), f["translucencyByDistance"], "{context}: translucency");
    assert_eq!(json!(flags.distance_display_condition), f["distanceDisplayCondition"], "{context}: ddc");
    assert_eq!(json!(flags.disable_depth_distance), f["disableDepthDistance"], "{context}: disableDepth");
    assert_eq!(collection.max_pixel_size(), num(&f["maxPixelSize"]), "{context}: maxPixelSize");
    let usage: Vec<u32> = collection.buffers_usage().iter().map(|u| *u as u32).collect();
    assert_eq!(json!(usage), f["buffersUsage"], "{context}: buffersUsage");
    assert_eq!(json!(collection.properties_changed()), f["propertiesChanged"], "{context}: propertiesChanged");
    assert_eq!(json!(collection.points_to_update()), f["toUpdateIndex"], "{context}: toUpdateIndex");

    let expected = step["points"].as_array().unwrap();
    for (i, (p, e)) in points.iter().zip(expected).enumerate() {
        if p.is_attached() {
            assert_eq!(json!(p.index()), e["index"], "{context}: point {i} index");
        }
        assert_eq!(json!(p.is_dirty()), e["dirty"], "{context}: point {i} dirty");
        let a = p.actual_position();
        for (k, v) in [a.x, a.y, a.z].iter().enumerate() {
            assert_close(*v, &e["actual"][k], &format!("{context}: point {i} actual[{k}]"));
        }
    }
}

/// `computeScreenSpacePosition` through a scene camera matching the capture's.
fn check_screen(
    collection: &PointPrimitiveCollection<Host>,
    points: &[PointPrimitive],
    camera: &Value,
    expected: &Value,
    context: &str,
) {
    if expected.is_null() {
        return;
    }
    let mut options = CameraOptions::new(8., 8.);
    options.client_width = 800.;
    options.client_height = 600.;
    let mut c = Camera::new(options);
    let mut frustum = PerspectiveFrustum::new(std::f64::consts::PI / 3., 4. / 3.);
    (frustum.near, frustum.far) = (1., 1e9);
    c.frustum = CameraFrustum::Perspective(frustum);
    (c.position, c.direction, c.up, c.right) =
        (c3(&camera["position"]), c3(&camera["direction"]), c3(&camera["up"]), c3(&camera["right"]));
    c.update(SceneMode::Scene3D).unwrap();
    let projection = GeographicProjection::default();
    let state = SceneTransformState {
        mode: SceneMode::Scene3D,
        morph_time: 1.,
        map_projection: &projection,
        client_dimensions: Cartesian2::new(800., 600.),
        drawing_buffer_dimensions: Cartesian2::new(8., 8.),
    };
    for (i, (p, e)) in points.iter().zip(expected.as_array().unwrap()).enumerate() {
        let actual = collection.compute_screen_space_position(p, &state, &mut c);
        if e.is_null() {
            assert_eq!(actual.unwrap_err().message, "PointPrimitive must be in a collection.", "{context}: screen {i}");
            continue;
        }
        let w = actual.unwrap().unwrap();
        assert_close(w.x, &e[0], &format!("{context}: screen {i} x"));
        assert_close(w.y, &e[1], &format!("{context}: screen {i} y"));
    }
}

#[test]
fn updates_match_cesium_vertex_bytes_commands_and_shaders() {
    let fixture: Value = serde_json::from_str(include_str!("data/scene-point-primitive-collection.json")).unwrap();
    let capture = &fixture["capture"];
    let max_point_size = capture["maximumAliasedPointSize"].as_f64().unwrap();
    let mut steps_checked = 0;
    for (name, script) in fixture["scenarios"].as_object().unwrap() {
        let host = Host { next: Rc::default(), max_point_size, uploads: Rc::default() };
        let context = Context::new_webgl2(host.clone());
        let scenario = &capture["scenarios"][name];
        let mut frame = frame(&context, &scenario["camera"]);
        let mut collection = PointPrimitiveCollection::<Host>::default();
        let mut points: Vec<PointPrimitive> = Vec::new();
        let mut steps = scenario["steps"].as_array().unwrap().iter();
        let mut previous = (None, None);
        for (op_index, op) in script.as_array().unwrap().iter().enumerate() {
            let kind = op[0].as_str().unwrap();
            let context_name = format!("{name} op {op_index} {op}");
            match kind {
                "add" => points.push(collection.add(options(&op[1])).unwrap()),
                "set" => set(&points[op[1].as_u64().unwrap() as usize], op[2].as_str().unwrap(), &op[3]),
                "remove" => {
                    let removed = collection.remove(&points[op[1].as_u64().unwrap() as usize]).unwrap();
                    let step = steps.next().unwrap();
                    assert_eq!(json!(removed), step["removed"], "{context_name}");
                    steps_checked += 1;
                }
                "removeAll" => collection.remove_all().unwrap(),
                "collection" => match op[1].as_str().unwrap() {
                    "blendOption" => {
                        collection.blend_option = BlendOption::from_value(op[2].as_i64().unwrap() as i32).unwrap()
                    }
                    "modelMatrix" => {
                        let m = nums(&op[2]);
                        collection.model_matrix = Matrix4(m.try_into().unwrap());
                    }
                    "show" => collection.show = op[2].as_bool().unwrap(),
                    "debugShowBoundingVolume" => collection.debug_show_bounding_volume = op[2].as_bool().unwrap(),
                    other => panic!("unknown collection property {other}"),
                },
                "update" => {
                    let o = &op[1];
                    let mode = SceneMode::from_value(o["mode"].as_i64().unwrap() as i32).unwrap();
                    frame.mode = mode;
                    frame.morph_time =
                        o["morphTime"].as_f64().unwrap_or(if mode == SceneMode::Scene3D { 1. } else { 0. });
                    frame.passes.render = o["render"].as_bool().unwrap_or(true);
                    frame.passes.pick = o["pick"].as_bool().unwrap_or(false);
                    frame.minimum_disable_depth_test_distance =
                        Some(o["minimumDisableDepthTestDistance"].as_f64().unwrap_or(0.));
                    frame.command_list.clear();
                    host.uploads.borrow_mut().clear();
                    collection.update(&mut frame).unwrap();
                    assert_eq!(frame.command_list.len(), collection.commands().len(), "{context_name}: queued");
                    let step = steps.next().unwrap();
                    assert_eq!(step["op"], *op);
                    let uploads: Vec<Value> = host.uploads.borrow().clone();
                    let expected: Vec<Value> = step["uploads"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|u| json!([u[0], num(&u[1]), u[2], u[3]]))
                        .collect();
                    let uploads: Vec<Value> = uploads.iter().map(|u| json!([u[0], num(&u[1]), u[2], u[3]])).collect();
                    assert_eq!(uploads, expected, "{context_name}: vertex uploads");
                    check_step(&collection, &points, step, &mut previous, &context_name);
                    check_screen(&collection, &points, &scenario["camera"], &step["screen"], &context_name);
                    steps_checked += 1;
                }
                other => panic!("unknown op {other}"),
            }
        }
        assert!(steps.next().is_none(), "{name}: unreplayed steps");
        collection.destroy().unwrap();
        assert!(points.iter().all(|p| !p.is_attached()));
    }
    assert_eq!(steps_checked, 36);
}
